package rpg.engine.world;import org.junit.jupiter.api.*;import rpg.engine.core.component.*;import rpg.engine.core.math.*;import static org.junit.jupiter.api.Assertions.*;
class CollisionTest{@Test void blocksBoxes(){var w=new GameWorld();var a=w.spawn();var b=w.spawn();w.entities().set(a,new Transform(new WorldPosition(0,0,0),0));w.entities().set(b,new Transform(new WorldPosition(2,0,0),0));w.entities().set(a,new BoxCollider(new Vec2(.6,.6)));w.entities().set(b,new BoxCollider(new Vec2(.6,.6)));assertFalse(w.collision().canOccupy(a,new WorldPosition(1,0,0)));assertTrue(w.collision().canOccupy(a,new WorldPosition(0,2,0)));}}
